const orders = $input.first().json.orders || [];

if (!orders.length) {
  return [{ json: { result: 'No order found with that order number or email. Please double-check the order number (it should look like #YFBS1234) or the email address used at checkout.' } }];
}

const o = orders[0];

// Format line items
const items = (o.line_items || [])
  .map(i => `• ${i.name} x${i.quantity} — ₹${i.price}`)
  .join('\n');

// Format fulfillment / tracking
const fulfillment = o.fulfillments?.[0];
const tracking = fulfillment?.tracking_number
  ? `Tracking No: ${fulfillment.tracking_number}${fulfillment.tracking_url ? ' (' + fulfillment.tracking_url + ')' : ''}`
  : null;

// Financial & fulfillment status labels
const payStatus = {
  paid: '✅ Paid',
  pending: '⏳ Payment Pending',
  refunded: '↩️ Refunded',
  partially_refunded: '↩️ Partially Refunded',
  voided: '❌ Voided'
}[o.financial_status] || o.financial_status;

const shipStatus = {
  fulfilled: '📦 Shipped',
  partial: '📦 Partially Shipped',
  unfulfilled: '🕐 Not Yet Shipped',
  restocked: '↩️ Restocked'
}[o.fulfillment_status] || o.fulfillment_status || '🕐 Not Yet Shipped';

const placedDate = new Date(o.created_at).toLocaleDateString('en-IN', {
  day: 'numeric', month: 'long', year: 'numeric'
});

const lines = [
  `Order ${o.name}`,
  `Placed on: ${placedDate}`,
  `Payment: ${payStatus}`,
  `Delivery: ${shipStatus}`,
  ``,
  `Items:`,
  items,
  tracking ? `\n${tracking}` : ''
].filter(l => l !== undefined).join('\n');

return [{ json: { result: lines } }];
